import csv
from pathlib import Path
trans_path = Path('csv/trans.csv')
ops = {}
with trans_path.open(newline='', encoding='utf-8') as f:
    reader = csv.DictReader(f)
    for r in reader:
        if r['account_id']=='2779':
            ops[r['operation']] = ops.get(r['operation'],0)+1

# print sorted
for op,count in sorted(ops.items(), key=lambda x: -x[1]):
    print(count, op)

